    need(len(mapping['parts'])==3 and sha(candidate)==mapping['candidate']['sha256'] and candidate.startswith(wrapper),'Accepted candidate differs')
    need(candidate==b''.join(source(x['assembly_path']) for x in mapping['parts']),'Accepted parts do not reconstruct')
    x=mapping['parts'][-1];b=source(x['assembly_path']);i,j=x['candidate_byte_start_inclusive'],x['candidate_byte_end_exclusive']
    need(sha(b)==x['sha256']==CORE_SHAS[0] and candidate[i:j]==b and candidate.count(b)==1,'Complete original proof differs')
    need(candidate[:i].count(b'\n')+1==x['candidate_line_start_1based'] and candidate[:j].count(b'\n')==x['candidate_line_end_inclusive'],'Accepted extraction lines differ');cores.append(b)
